import itertools

def solve():
    num_vertices = 9
    fixed_edges = [(5, 7), (1, 5), (3, 6), (5, 6), (4, 5), (4, 6), (0, 7)]

    # All possible edges
    all_possible_edges = []
    for i in range(num_vertices):
        for j in range(i + 1, num_vertices):
            if (i, j) not in fixed_edges and (j, i) not in fixed_edges:
                all_possible_edges.append((i, j))

    # We need to add edges until all degrees are >= 5
    # Let's try to add edges greedily or use a solver

    import networkx as nx

    G = nx.Graph()
    G.add_nodes_from(range(num_vertices))
    G.add_edges_from(fixed_edges)

    # Current degrees
    def get_degrees(graph):
        return [graph.degree(i) for i in range(num_vertices)]

    # Add edges to satisfy the condition
    for edge in all_possible_edges:
        if all(d >= 5 for d in get_degrees(G)):
            break
        G.add_edge(*edge)

    if all(d >= 5 for d in get_degrees(G)):
        return list(G.edges())
    else:
        return None

print(solve())
